{
  "title": "Kyoto with a full belly",
  "summary": "A temple morning, a market graze, and a proper evening meal so Rin can eat her way through the day.",
  "stops": [
    {
      "poi_id": "p12",
      "kind": "activity",
      "must_do_id": "m2",
      "note": "Shoes off, phone down, eyes up. Kept as the must-do, early before the day gets delicious.",
      "must_do_id": "m2"
    },
    {
      "poi_id": "p4",
      "kind": "activity",
      "must_do_id": null,
      "note": "Rin wanted to graze, so this is the snack parade. Lunch is whatever catches her eye.",
      "must_do_id": null
    },
    {
      "poi_id": "p3",
      "kind": "activity",
      "must_do_id": null,
      "note": "A viewpoint with a full stomach is still a viewpoint. We arrive before the light goes soft.",
      "must_do_id": null
    },
    {
      "poi_id": "p20",
      "kind": "meal",
      "must_do_id": null,
      "note": "A proper sit-down meal with vegetarian options, because grazing all day deserves a table.",
      "must_do_id": null
    }
  ]
}
